# --------------------------------------------------------------------------
# Construccion. Se les pasan los ayudantes de terreno_mar.py para no depender
# de imports: por el puente viaja texto pegado, no una carpeta.
# --------------------------------------------------------------------------
import random


def _centro(pts):
    return (sum(p[0] for p in pts) / len(pts), sum(p[1] for p in pts) / len(pts))


def centros():
    """Donde ya hay edificio real, para que el relleno no se encime."""
    return [_centro(p) for p, _ in EDIF]


def edificios(bpy, bmesh, z_en, ORIG_X, ORIG_Y, mat, a_coleccion, rehacer, COL):
    rehacer("COLONIA_osm")
    rnd = random.Random(7)
    bm = bmesh.new()
    n = 0
    for pts, niveles in EDIF:
        cx, cy = _centro(pts)
        z = z_en(cx + ORIG_X, cy + ORIG_Y)
        alto = (niveles * 2.85) if niveles else rnd.choice((2.9, 3.1, 5.6, 5.6, 6.2))
        abajo = [bm.verts.new((x + ORIG_X, y + ORIG_Y, z - 0.5)) for x, y in pts]
        arriba = [bm.verts.new((x + ORIG_X, y + ORIG_Y, z + alto)) for x, y in pts]
        for i in range(len(pts)):
            j = (i + 1) % len(pts)
            try:
                bm.faces.new((abajo[i], abajo[j], arriba[j], arriba[i]))
            except ValueError:
                pass                      # huella con nodos repetidos: se salta
        try:
            bm.faces.new(arriba)
        except ValueError:
            pass
        n += 1
    me = bpy.data.meshes.new("COLONIA_osm")
    bm.to_mesh(me); bm.free()
    ob = bpy.data.objects.new("COLONIA_osm", me)
    bpy.context.scene.collection.objects.link(ob)
    a_coleccion(ob, COL)
    ob.data.materials.append(mat("TER_colonia", (0.62, 0.585, 0.535, 1), 0.9, 60.0))
    ob.data.materials.append(mat("TER_azotea", (0.30, 0.29, 0.275, 1), 0.92))
    ob.data.materials.append(mat("TER_teja", (0.235, 0.085, 0.045, 1), 0.9))
    rnd2 = random.Random(3)
    for p in me.polygons:
        if len(p.vertices) > 4 or p.normal.z > 0.7:      # la azotea
            p.material_index = rnd2.choice((1, 1, 2, 0))
    return n, len(me.vertices)


def calles(bpy, bmesh, z_en, ORIG_X, ORIG_Y, mat, a_coleccion, rehacer, COL):
    """El trazo real de las calles: es lo que hace que desde el aire se lea
    como el fraccionamiento y no como un monton de cajas."""
    rehacer("COLONIA_calles")
    import math
    bm = bmesh.new()
    n = 0
    for pts, ancho in VIAS:
        h = ancho / 2.0
        anillo = None
        for i, (x, y) in enumerate(pts):
            if i == 0:
                dx, dy = pts[1][0] - x, pts[1][1] - y
            elif i == len(pts) - 1:
                dx, dy = x - pts[-2][0], y - pts[-2][1]
            else:
                dx, dy = pts[i+1][0] - pts[i-1][0], pts[i+1][1] - pts[i-1][1]
            L = math.hypot(dx, dy) or 1.0
            nx, ny = -dy / L * h, dx / L * h
            xa, ya = x + ORIG_X, y + ORIG_Y
            a = bm.verts.new((xa + nx, ya + ny, z_en(xa + nx, ya + ny) + 0.10))
            b = bm.verts.new((xa - nx, ya - ny, z_en(xa - nx, ya - ny) + 0.10))
            if anillo:
                try:
                    bm.faces.new((anillo[0], a, b, anillo[1]))
                except ValueError:
                    pass
            anillo = (a, b)
        n += 1
    me = bpy.data.meshes.new("COLONIA_calles")
    bm.to_mesh(me); bm.free()
    ob = bpy.data.objects.new("COLONIA_calles", me)
    bpy.context.scene.collection.objects.link(ob)
    a_coleccion(ob, COL)
    ob.data.materials.append(mat("TER_asfalto", (0.055, 0.055, 0.055, 1), 0.85))
    return n, len(me.polygons)
